{#- Pre-printed yellow pad (A5 landscape, 210 x 148 mm): only values are printed.
    If the print lands off the pad's labels, change dx / dy below (mm, + = right / down). -#}
{%- set dx = 0 -%}
{%- set dy = 0 -%}
{%- set fd = "dd/MM/yyyy" -%}
{%- set party = (frappe.db.get_value("Supplier", doc.party_name, "supplier_name") if doc.party_name else "") or doc.party_name or "" -%}
{%- set carrier = (frappe.db.get_value("Supplier", doc.transporter, "supplier_name") if doc.transporter else "") or doc.transporter or "" -%}
{%- set tractor = (frappe.db.get_value("Tractor Number", doc.vehicle_no, "tractor_number") if doc.vehicle_no else "") or doc.vehicle_no or "" -%}
{%- set item = (doc.product_name or "") ~ (" - " ~ doc.description if doc.description else "") -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
.print-format { page-size: A5; orientation: Landscape; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; padding: 0; }
@page { size: A5 landscape; margin: 0; }
.gws, .gws div { font-family: "Noto Sans", "Liberation Sans", Arial, sans-serif; color: #000; }
.gws { position: relative; width: 209mm; height: 146mm; overflow: hidden; }
.gws .in { position: absolute; left: {{ dx }}mm; top: {{ dy }}mm; width: 209mm; height: 146mm; }
.gws .a { position: absolute; font-weight: bold; white-space: nowrap; overflow: hidden; }
.gws .vl { font-size: 15px; line-height: 7mm; }
.gws .it { font-size: 12.5px; line-height: 4.3mm; white-space: normal; }
.gws .wv { font-size: 17px; line-height: 6.6mm; text-align: right; }
</style>
<div class="gws"><div class="in">
<div class="a vl" style="left:59mm; top:46.3mm; width:64mm">{{ doc.name }}</div>
<div class="a vl" style="left:59mm; top:64.0mm; width:64mm">{{ party }}</div>
<div class="a vl" style="left:59mm; top:72.9mm; width:64mm">{{ carrier }}</div>
<div class="a vl" style="left:59mm; top:81.8mm; width:64mm">{{ doc.place or "" }}</div>
{% if item|length <= 30 %}<div class="a vl" style="left:59mm; top:55.2mm; width:64mm">{{ item }}</div>{% else %}<div class="a it" style="left:59mm; top:54.4mm; width:64mm; height:8.6mm">{{ item }}</div>{% endif %}
<div class="a vl" style="left:150mm; top:47.0mm; width:56mm">{{ frappe.utils.formatdate(doc.slip_date, fd) }}</div>
<div class="a vl" style="left:150mm; top:55.3mm; width:56mm">{{ doc.vehicle_type or "" }}</div>
<div class="a vl" style="left:150mm; top:63.9mm; width:56mm">{{ tractor }}</div>
<div class="a wv" style="left:127mm; top:93.3mm; width:28mm">{{ "%g"|format(doc.loaded_weight or 0) }} Kg</div>
<div class="a wv" style="left:127mm; top:102.4mm; width:28mm">{{ "%g"|format(doc.empty_weight or 0) }} Kg</div>
<div class="a wv" style="left:127mm; top:111.4mm; width:28mm">{{ "%g"|format(doc.net_weight or 0) }} Kg</div>
</div></div>
